  const inWin = x>=winX&&x<winW+winX&&y>=winY&&y<winH+winY;
  const borderW = x>=winX&&x<winW+winX&&(y>=winY&&y<winY+2||y>=winH+winY-2&&y<winH+winY)||(y>=winY&&y<winH+winY)&&(x>=winX&&x<winX+2||x>=winW+winX-2&&x<winW+winX);
  if(borderW) uiMask=0.8;
